uniform float2 size;
uniform float time;
uniform half4 colorA; // Color 1: #FF6B4A
uniform half4 colorB; // Color 2: #FFC24B
uniform half4 colorC; // Color 3: #6B5BFF
uniform half4 colorD; // Color 4: #2DD4BF
uniform float warp; // Warp: 0.5 (0..1)
uniform float speed; // Speed: 0.3 (0..2)

half4 main(float2 p) {
  float2 uv = p / size;
  float t = time * speed;
  uv += warp * 0.22 * float2(sin(uv.y * 5.0 + t), cos(uv.x * 4.0 - t * 1.3));
  float sx = smoothstep(0.0, 1.0, uv.x);
  half4 top = mix(colorA, colorB, half(sx));
  half4 bottom = mix(colorC, colorD, half(sx));
  return mix(top, bottom, half(smoothstep(0.0, 1.0, uv.y)));
}

