uniform float height; // Warp: 0.06 (0..0.3)
uniform float speed; // Speed: 0.6 (0..3)

half4 main(float2 p) {
  float2 uv = p / size;
  float y = uv.y + height * sin(uv.x * 12.566 + time * speed);
  float s = 0.5 + 0.5 * sin(y * count * 6.2832);
  return mix(colorA, colorB, half(smoothstep(0.3, 0.7, s)));
}

exact.uniform float2 size;\nuniform half4 colo:
uniform float2 size;
uniform half4 colorA; // Background: #FFFFFF
uniform half4 colorB; // Dots: #111827
uniform float cell; // Spacing: 14 (3..60)
uniform float angle; // Tilt: 45 (0..90)

half4 main(float2 p) {
  float a = radians(angle);
  float2 q = float2(cos(a) * p.x - sin(a) * p.y, sin(a) * p.x + cos(a) * p.y) / cell;
  float2 f = fract(q) - 0.5;
  float tone = clamp(1.0 - (p.x / size.x + p.y / size.y) * 0.5, 0.0, 1.0);
  float r = 0.62 * sqrt(tone);
  float edge = 1.0 / cell;
  float m = 1.0 - smoothstep(r - edge, r + edge, length(f));
  return mix(colorA, colorB, half(m));
}

exact.uniform float2 size;\nuniform float time:
uniform float2 size;
uniform float time;
uniform float scale; // Scale: 1 (0.2..5)
uniform float speed; // Speed: 0.5 (0..3)
uniform float shift; // Hue: 0 (0..6.28)

half4 main(float2 p) {
  float2 uv = p / max(size.x, size.y) * 6.0 * scale;
  float t = time * speed;
  float v = sin(uv.x + t) + sin(uv.y * 1.3 - t) + sin((uv.x + uv.y) * 0.7 + t * 0.7) + sin(length(uv - 3.0) * 1.5 - t);
  float3 c = 0.5 + 0.5 * sin(v + shift + float3(0.0, 2.1, 4.2));
  return half4(half3(c), 1.0);
}

